<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { ArrowLeft, Copy, LogOut, Plus, Users } from 'lucide-vue-next'
import { isSupabaseConfigured, requireSupabase } from '../services/supabase'
import { sessionQuestionBank } from '../data/sessionQuestionBank'
type SessionRow={id:string;code:string;title:string;mode:'self_paced'|'live';status:string;created_at:string}
type Participant={id:string;nickname:string;score:number;joined_at:string;finished_at:string|null;correct:number;incorrect:number}
const email=ref(''),loggedIn=ref(false),busy=ref(false),message=ref('')
const sessions=ref<SessionRow[]>([]),selectedSession=ref<SessionRow|null>(null),participants=ref<Participant[]>([])
const title=ref('Prueba de guitarra'),mode=ref<'self_paced'|'live'>('self_paced')
let channel:any=null
const shareUrl=computed(()=>selectedSession.value?`${window.location.origin}/sesion/${selectedSession.value.code}`:'')
async function sendLogin(){busy.value=true;message.value='';try{const {error}=await requireSupabase().auth.signInWithOtp({email:email.value.trim(),options:{emailRedirectTo:window.location.origin+'/docente/sesiones'}});if(error)throw error;message.value='Te enviamos un enlace de acceso al correo. Ábrelo en este mismo navegador.'}catch(e){message.value=e instanceof Error?e.message:'No se pudo iniciar sesión.'}finally{busy.value=false}}
async function loadSessions(){const {data,error}=await requireSupabase().from('sessions').select('id,code,title,mode,status,created_at').order('created_at',{ascending:false});if(error)throw error;sessions.value=data as SessionRow[]}
async function refreshParticipants(){if(!selectedSession.value)return;const db=requireSupabase();const sid=selectedSession.value.id;const [pr,ar]=await Promise.all([db.from('participants').select('id,nickname,score,joined_at,finished_at').eq('session_id',sid).order('score',{ascending:false}),db.from('session_answers').select('participant_id,is_correct').eq('session_id',sid)]);if(pr.error)throw pr.error;if(ar.error)throw ar.error;participants.value=(pr.data??[]).map(p=>{const answers=(ar.data??[]).filter(a=>a.participant_id===p.id);return {...p,correct:answers.filter(a=>a.is_correct).length,incorrect:answers.filter(a=>!a.is_correct).length}}) as Participant[]}
async function createSession(){busy.value=true;message.value='';try{const questions=sessionQuestionBank.map(q=>({category:q.category,prompt:q.prompt,options:q.options,correct_answer:q.correct,explanation:q.explanation,midi:q.midi??null}));const {data,error}=await requireSupabase().rpc('create_class_session',{p_title:title.value.trim()||'Sesión de evaluación',p_mode:mode.value,p_questions:questions});if(error)throw error;await loadSessions();selectedSession.value=data as SessionRow;await refreshParticipants();subscribe();message.value='Sesión creada. Comparte el enlace o el código con tus estudiantes.'}catch(e){message.value=e instanceof Error?e.message:'No se pudo crear la sesión.'}finally{busy.value=false}}
async function selectSession(s:SessionRow){selectedSession.value=s;try{await refreshParticipants();subscribe()}catch(e){message.value=e instanceof Error?e.message:'Error al cargar participantes.'}}
function subscribe(){if(channel)requireSupabase().removeChannel(channel);if(!selectedSession.value)return;const sid=selectedSession.value.id;channel=requireSupabase().channel('teacher-'+sid).on('postgres_changes',{event:'*',schema:'public',table:'participants',filter:'session_id=eq.'+sid},()=>refreshParticipants()).on('postgres_changes',{event:'*',schema:'public',table:'sessions',filter:'id=eq.'+sid},async payload=>{if(selectedSession.value)selectedSession.value={...selectedSession.value,...payload.new as Partial<SessionRow>};await loadSessions()}).subscribe()}
async function control(action:'start'|'next'|'finish'){if(!selectedSession.value)return;const fn=action==='start'?'start_class_session':action==='next'?'advance_class_session':'finish_class_session';const {error}=await requireSupabase().rpc(fn,{p_session_id:selectedSession.value.id});if(error){message.value=error.message;return}await loadSessions();const latest=sessions.value.find(s=>s.id===selectedSession.value?.id);if(latest)selectedSession.value=latest;await refreshParticipants()}
async function copy(value:string){try{await navigator.clipboard.writeText(value);message.value='Copiado al portapapeles.'}catch{message.value=value}}
async function logout(){await requireSupabase().auth.signOut();loggedIn.value=false;sessions.value=[];selectedSession.value=null;participants.value=[]}
onMounted(async()=>{if(!isSupabaseConfigured)return;const db=requireSupabase();const {data}=await db.auth.getSession();loggedIn.value=Boolean(data.session&&!data.session.user.is_anonymous);if(loggedIn.value)try{await loadSessions()}catch(e){message.value=e instanceof Error?e.message:'Error al cargar sesiones.'}db.auth.onAuthStateChange((_event,s)=>{loggedIn.value=Boolean(s&&!s.user.is_anonymous);if(loggedIn.value)loadSessions().catch(e=>message.value=e.message)})})
onUnmounted(()=>{if(channel)requireSupabase().removeChannel(channel)})
</script>
<template>
<div class="page">
 <div class="mb-6 flex items-center gap-3"><RouterLink to="/" class="secondary"><ArrowLeft :size="17"/></RouterLink><div><p class="eyebrow">Herramientas docentes</p><h1 class="text-2xl font-black sm:text-3xl">Sesiones de evaluación</h1></div></div>
 <section v-if="!isSupabaseConfigured" class="panel p-6"><h2 class="text-xl font-black">Falta conectar Supabase</h2><p class="mt-2 text-sm leading-6 text-[#687970]">La interfaz está preparada. Configura el proyecto Supabase y las variables de entorno siguiendo <code>supabase/README.md</code> y <code>.env.example</code>.</p></section>
 <section v-else-if="!loggedIn" class="panel mx-auto max-w-xl p-6 sm:p-8"><div class="grid h-12 w-12 place-items-center rounded-2xl bg-[#e8f2eb] text-[#26745a]"><Users/></div><h2 class="mt-4 text-xl font-black">Acceso docente</h2><p class="mt-2 text-sm text-[#718078]">Escribe tu correo. Recibirás un enlace seguro para administrar tus sesiones.</p><form class="mt-5 space-y-3" @submit.prevent="sendLogin"><label class="block text-sm font-bold">Correo electrónico</label><input v-model="email" type="email" required autocomplete="email" class="w-full rounded-xl border border-[#dce6dd] px-4 py-3" placeholder="docente@institucion.edu"/><button class="primary w-full justify-center" :disabled="busy">{{busy?'Enviando…':'Enviar enlace de acceso'}}</button></form><p v-if="message" class="mt-3 text-sm text-[#37644f]">{{message}}</p></section>
 <template v-else>
  <div class="mb-4 flex justify-end"><button class="secondary inline-flex items-center gap-2" @click="logout"><LogOut :size="16"/> Cerrar sesión</button></div>
  <div class="grid gap-4 lg:grid-cols-[.85fr_1.15fr]">
   <section class="panel p-5 sm:p-6"><h2 class="text-lg font-black">Crear una sesión</h2><p class="mt-1 text-sm text-[#718078]">Banco inicial de 12 preguntas de Guitar Tutor.</p><form class="mt-5 space-y-4" @submit.prevent="createSession">
    <div><label class="mb-1 block text-sm font-bold">Nombre de la sesión</label><input v-model="title" required maxlength="90" class="w-full rounded-xl border border-[#dce6dd] px-3 py-3"/></div>
    <div><label class="mb-2 block text-sm font-bold">Modalidad</label><label class="mb-2 flex cursor-pointer gap-3 rounded-xl border p-3" :class="mode==='self_paced'?'border-[#398568] bg-[#f0f7f1]':'border-[#e2e9e3]'"><input v-model="mode" type="radio" value="self_paced" class="mt-1 accent-[#26745a]"/><span><b class="block text-sm">Cada estudiante a su ritmo</b><small class="text-[#718078]">Cada participante responde de forma independiente.</small></span></label><label class="flex cursor-pointer gap-3 rounded-xl border p-3" :class="mode==='live'?'border-[#398568] bg-[#f0f7f1]':'border-[#e2e9e3]'"><input v-model="mode" type="radio" value="live" class="mt-1 accent-[#26745a]"/><span><b class="block text-sm">En vivo, dirigida por el docente</b><small class="text-[#718078]">El docente abre cada pregunta para todos.</small></span></label></div>
    <button class="primary w-full justify-center" :disabled="busy"><Plus :size="17"/>{{busy?'Creando…':'Crear sesión'}}</button></form><p v-if="message" class="mt-3 rounded-xl bg-[#f0f5f0] p-3 text-sm text-[#37644f]">{{message}}</p></section>
   <section class="panel p-5 sm:p-6"><h2 class="text-lg font-black">Tus sesiones</h2><p v-if="!sessions.length" class="mt-3 text-sm text-[#718078]">Todavía no has creado sesiones.</p><div v-else class="mt-3 space-y-2"><button v-for="s in sessions" :key="s.id" class="flex w-full items-center justify-between rounded-xl border p-3 text-left hover:bg-[#f5f8f5]" :class="selectedSession?.id===s.id?'border-[#398568] bg-[#f0f7f1]':'border-[#e4ebe5]'" @click="selectSession(s)"><span class="min-w-0"><b class="block truncate text-sm">{{s.title}}</b><small class="text-[#718078]">{{s.code}} · {{s.mode==='live'?'En vivo':'A su ritmo'}}</small></span><span class="rounded-full bg-[#edf4ee] px-2 py-1 text-xs font-bold">{{s.status}}</span></button></div>
    <div v-if="selectedSession" class="mt-5 border-t border-[#e8eee8] pt-4"><div class="flex flex-wrap items-center justify-between gap-2"><h3 class="font-extrabold">Compartir con estudiantes</h3><span class="text-xs text-[#718078]">Código: <b>{{selectedSession.code}}</b></span></div><div class="mt-3 flex gap-2"><input readonly :value="shareUrl" class="min-w-0 flex-1 rounded-xl border border-[#dce6dd] bg-[#f8faf8] px-3 py-2 text-xs"/><button class="secondary" title="Copiar enlace" @click="copy(shareUrl)"><Copy :size="16"/></button></div><button class="mt-2 text-sm font-bold text-[#26745a]" @click="copy(selectedSession.code)">Copiar código manual</button>
     <div class="mt-5 flex flex-wrap gap-2" v-if="selectedSession.status!=='finished'"><button v-if="selectedSession.status==='lobby'" class="primary" @click="control('start')">{{selectedSession.mode==='live'?'Iniciar sesión':'Abrir prueba'}}</button><template v-else-if="selectedSession.mode==='live'"><button class="primary" @click="control('next')">Siguiente pregunta</button><button class="secondary" @click="control('finish')">Finalizar sesión</button></template><button v-else class="secondary" @click="control('finish')">Cerrar prueba</button></div>
     <div class="mt-5 flex items-center justify-between"><h3 class="font-extrabold">Resultados del grupo</h3><span class="text-xs text-[#718078]">{{participants.length}} participantes</span></div><p v-if="!participants.length" class="mt-3 rounded-xl bg-[#f5f8f5] p-4 text-sm text-[#718078]">Aún no han ingresado estudiantes.</p><div v-else class="mt-3 space-y-2"><div v-for="(p,i) in participants" :key="p.id" class="rounded-xl bg-[#f5f8f5] p-3"><div class="flex items-center justify-between gap-2"><span class="text-sm font-bold">{{i+1}}. {{p.nickname}} <small v-if="p.finished_at" class="font-normal text-[#398568]">· finalizó</small></span><b class="text-sm tabular-nums">{{p.score}} pts</b></div><p class="mt-1 text-xs text-[#718078]">{{p.correct}} correctas · {{p.incorrect}} incorrectas</p></div></div>
    </div>
   </section>
  </div>
 </template>
</div>
</template>
